/**
 * @file
 * Use Views AJAX instead of full page reload when editorial search facets change.
 */

(function ($, Drupal, once, drupalSettings) {
  'use strict';

  /** Event series bundle in the content_type facet (label: Event). */
  const EVENT_CONTENT_TYPE_FACET = 'content_type:default';

  /** Query parameter for including past events in editorial search results. */
  const SHOW_PAST_EVENTS_QUERY_KEY = 'show_past_events';

  /** Event facet checkbox ID generated by Facets. */
  const EVENT_FACET_CHECKBOX_ID = 'content-type-default';

  /** Re-apply Event facet sort in the UI after the next Views AJAX response. */
  let pendingEventSortUi = null;

  /**
   * Returns the editorial search view element.
   */
  function getEditorialSearchView() {
    return $('.eonext-editorial-search').first();
  }

  /**
   * Returns whether a checkbox is the Event content type facet.
   */
  function isEventCheckbox(checkbox) {
    return checkbox.id === EVENT_FACET_CHECKBOX_ID
      || checkbox.value === EVENT_CONTENT_TYPE_FACET
      || $(checkbox).data('drupalFacetFilterValue') === EVENT_CONTENT_TYPE_FACET;
  }

  /**
   * Returns whether a query parameter key is a facet filter key.
   */
  function isFacetQueryKey(key) {
    return key === 'f[]' || /^f(\[\d*\])?$/.test(key);
  }

  /**
   * Builds the request URL for an Event facet toggle with explicit sort params.
   */
  function buildEventFacetUrl(href, sortBy, sortOrder) {
    const target = new URL(href, window.location.href);
    const merged = new URL(window.location.href);

    // Drop existing facet filters; facetsredir may be stale after sort changes.
    [...merged.searchParams.keys()].forEach((key) => {
      if (isFacetQueryKey(key)) {
        merged.searchParams.delete(key);
      }
    });

    // Apply facet filters from the facet link target URL.
    target.searchParams.forEach((value, key) => {
      if (isFacetQueryKey(key)) {
        merged.searchParams.append(key, value);
      }
    });

    merged.searchParams.set('sort_by', sortBy);
    merged.searchParams.set('sort_order', sortOrder);
    merged.searchParams.delete('page');

    return merged.pathname + merged.search;
  }

  /**
   * Syncs the sort dropdowns with the active sort query params.
   */
  function updateSortControls($view, sortBy, sortOrder) {
    const viewElement = $view && $view.length ? $view[0] : document.querySelector('.eonext-editorial-search');

    if (!viewElement) {
      return;
    }

    const sortField = viewElement.querySelector('[data-editorial-search-sort]');
    const sortOrderSelect = viewElement.querySelector('[data-editorial-search-sort-order]');

    if (sortField) {
      sortField.value = sortBy;
    }

    if (sortOrderSelect) {
      sortOrderSelect.value = sortOrder;
    }
  }

  /**
   * Find the Views AJAX instance for the editorial search view.
   */
  function getViewAjaxInstance($view) {
    const instances = Drupal.views.instances || {};
    const $editorialView = $view && $view.length ? $view : getEditorialSearchView();

    if (!$editorialView.length) {
      return null;
    }

    let instance = Object.values(instances).find(
      (item) => item.$view && item.$view.length && item.$view.is($editorialView),
    );

    if (instance) {
      return instance;
    }

    const domIdClass = $editorialView.attr('class')
      ?.split(/\s+/)
      .find((className) => className.startsWith('js-view-dom-id-'));

    if (!domIdClass) {
      return null;
    }

    instance = Object.values(instances).find(
      (item) => item.$view && item.$view.length && item.$view.hasClass(domIdClass),
    );

    return instance || null;
  }

  /**
   * Build the Views AJAX request URL from the current browser query string.
   */
  function buildViewsAjaxUrl(baseUrl) {
    let queryString = window.location.search || '';
    if (queryString === '') {
      return baseUrl;
    }

    queryString = queryString
      .slice(1)
      .replace(/q=[^&]+&?|page=[^&]+&?|&?render=[^&]+/, '');

    if (queryString === '') {
      return baseUrl;
    }

    const separator = /\?/.test(baseUrl) ? '&' : '?';
    return baseUrl + separator + queryString;
  }

  /**
   * Update the request URL on a Views or Drupal Ajax object.
   */
  function updateAjaxUrl(ajaxObject, updatedUrl) {
    if (!ajaxObject) {
      return;
    }

    if (ajaxObject.element_settings) {
      ajaxObject.element_settings.url = updatedUrl;
    }

    if (ajaxObject.elementSettings) {
      ajaxObject.elementSettings.url = updatedUrl;
    }

    if (typeof ajaxObject.url === 'string') {
      ajaxObject.url = updatedUrl;
    }

    if (ajaxObject.options) {
      ajaxObject.options.url = updatedUrl;
    }
  }

  /**
   * Trigger a Views AJAX refresh for the editorial search view.
   */
  function refreshEditorialSearchView($view) {
    const instance = getViewAjaxInstance($view);
    if (!instance) {
      return false;
    }

    const ajaxPath = drupalSettings.views.ajax_path;
    const basePath = Array.isArray(ajaxPath) ? ajaxPath[0] : ajaxPath;
    const updatedUrl = buildViewsAjaxUrl(basePath);

    updateAjaxUrl(instance, updatedUrl);
    updateAjaxUrl(instance.refreshViewAjax, updatedUrl);

    if (instance.refreshViewAjax && typeof instance.refreshViewAjax.execute === 'function') {
      instance.refreshViewAjax.execute();
    }
    else {
      instance.$view.trigger('RefreshView');
    }

    return true;
  }

  /**
   * Updates sort query params and refreshes the editorial search view.
   */
  function applyEditorialSearchSort($view, sortBy, sortOrder) {
    const url = new URL(window.location.href);

    url.searchParams.set('sort_by', sortBy);
    url.searchParams.set('sort_order', sortOrder);
    url.searchParams.delete('page');

    window.history.pushState({}, document.title, url.toString());

    if (!refreshEditorialSearchView($view)) {
      window.location = url.toString();
    }
  }

  /**
   * Updates show_past_events query param and refreshes the editorial search view.
   */
  function applyEditorialSearchPastEventsToggle($view, showPastEvents) {
    const url = new URL(window.location.href);

    if (showPastEvents) {
      url.searchParams.set(SHOW_PAST_EVENTS_QUERY_KEY, '1');
    }
    else {
      url.searchParams.delete(SHOW_PAST_EVENTS_QUERY_KEY);
    }
    url.searchParams.delete('page');

    window.history.pushState({}, document.title, url.toString());

    if (!refreshEditorialSearchView($view)) {
      window.location = url.toString();
    }
  }

  /**
   * Apply date filter values to the URL and refresh the view via AJAX.
   */
  function applyEditorialSearchDateFilter($view) {
    const viewElement = $view && $view.length ? $view[0] : document.querySelector('.eonext-editorial-search');

    if (!viewElement) {
      return;
    }

    const minInput = viewElement.querySelector('input[name="date[min]"]');
    const maxInput = viewElement.querySelector('input[name="date[max]"]');
    const url = new URL(window.location.href);
    const minValue = minInput instanceof HTMLInputElement ? minInput.value : '';
    const maxValue = maxInput instanceof HTMLInputElement ? maxInput.value : '';

    if (minValue) {
      url.searchParams.set('date[min]', minValue);
    }
    else {
      url.searchParams.delete('date[min]');
    }

    if (maxValue) {
      url.searchParams.set('date[max]', maxValue);
    }
    else {
      url.searchParams.delete('date[max]');
    }

    url.searchParams.delete('page');
    window.history.pushState({}, document.title, url.toString());

    if (!refreshEditorialSearchView($view)) {
      window.location = url.toString();
    }
  }

  /**
   * Handle editorial search date filter changes via Views AJAX.
   */
  function handleDateFilterChange(event) {
    const input = event.currentTarget;

    if (!(input instanceof HTMLInputElement)) {
      return;
    }

    if (!input.closest('.eonext-editorial-search__date-filter')) {
      return;
    }

    applyEditorialSearchDateFilter($(input).closest('.eonext-editorial-search'));
  }

  /**
   * Handle past events toggle via Views AJAX.
   */
  function handlePastEventsToggle(event) {
    const checkbox = event.currentTarget;

    if (!(checkbox instanceof HTMLInputElement) || checkbox.type !== 'checkbox') {
      return;
    }

    const $view = $(checkbox).closest('.eonext-editorial-search');
    applyEditorialSearchPastEventsToggle($view, checkbox.checked);
  }

  /**
   * Sync past events toggle with the active query param after AJAX refresh.
   */
  function updatePastEventsToggle($view) {
    const viewElement = $view && $view.length ? $view[0] : document.querySelector('.eonext-editorial-search');

    if (!viewElement) {
      return;
    }

    const checkbox = viewElement.querySelector('[data-editorial-search-show-past-events]');

    if (!(checkbox instanceof HTMLInputElement)) {
      return;
    }

    const url = new URL(window.location.href);
    checkbox.checked = url.searchParams.get(SHOW_PAST_EVENTS_QUERY_KEY) === '1';
  }

  /**
   * Handle sort field or order dropdown changes via Views AJAX.
   */
  function handleSortChange(event) {
    const $sort = $(event.currentTarget).closest('.eonext-editorial-search__sort');
    const sortBy = $sort.find('[data-editorial-search-sort]').val();
    const sortOrder = $sort.find('[data-editorial-search-sort-order]').val();
    const $view = $sort.closest('.eonext-editorial-search');

    applyEditorialSearchSort($view, sortBy, sortOrder);
  }

  /**
   * Handle facet filter clicks via Views AJAX.
   */
  function handleFacetsFilter(event, url) {
    event.preventDefault();
    event.stopImmediatePropagation();

    const $widget = $(event.currentTarget);
    const $view = $widget.closest('.eonext-editorial-search');

    if (!$view.length) {
      window.location = url;
      return;
    }

    $view.find('.js-facets-widget').trigger('facets_filtering');
    window.history.pushState({}, document.title, url);

    if (!refreshEditorialSearchView($view)) {
      window.location = url;
    }
  }

  /**
   * When Event is toggled: update sort in the UI, then run the facet AJAX flow.
   */
  function handleEventFacetCheckboxChange(event) {
    const checkbox = event.target;

    if (!(checkbox instanceof HTMLInputElement) || checkbox.type !== 'checkbox') {
      return;
    }

    if (!checkbox.closest('.eonext-editorial-search') || !isEventCheckbox(checkbox)) {
      return;
    }

    event.stopPropagation();
    event.stopImmediatePropagation();

    const $checkbox = $(checkbox);
    const $widget = $checkbox.closest('.js-facets-widget');
    const $view = getEditorialSearchView();
    const href = $checkbox.data('facetsredir');

    if (!$view.length || !href) {
      return;
    }

    const sortBy = checkbox.checked ? 'sort_date' : 'relevance';
    const sortOrder = checkbox.checked ? 'ASC' : 'DESC';

    pendingEventSortUi = { sortBy, sortOrder };
    updateSortControls($view, sortBy, sortOrder);

    const updatedUrl = buildEventFacetUrl(href, sortBy, sortOrder);

    if (Drupal.facets && typeof Drupal.facets.disableFacet === 'function') {
      Drupal.facets.disableFacet($widget);
    }

    $view.find('.js-facets-widget').trigger('facets_filtering');
    window.history.pushState({}, document.title, updatedUrl);

    if (!refreshEditorialSearchView($view)) {
      window.location = updatedUrl;
    }
  }

  /**
   * Override default facets navigation after the core facets behavior attaches.
   */
  Drupal.behaviors.facetsFilterEditorialOverride = {
    weight: 100,

    attach(context) {
      once('editorial-search-event-facet', 'html').forEach((root) => {
        root.addEventListener('change', handleEventFacetCheckboxChange, true);
      });

      $('.eonext-editorial-search .js-facets-widget').each(function () {
        $(this).off('facets_filter.facets').on('facets_filter.facets', handleFacetsFilter);
      });

      once('editorial-search-sort', '.eonext-editorial-search [data-editorial-search-sort], .eonext-editorial-search [data-editorial-search-sort-order]', context).forEach((select) => {
        select.addEventListener('change', handleSortChange);
      });

      once('editorial-search-past-events', '.eonext-editorial-search [data-editorial-search-show-past-events]', context).forEach((checkbox) => {
        checkbox.addEventListener('change', handlePastEventsToggle);
      });

      once('editorial-search-date-filter', '.eonext-editorial-search__date-filter input[type="date"]', context).forEach((input) => {
        input.addEventListener('change', handleDateFilterChange);
      });

      once('editorial-search-popstate', 'html').forEach((root) => {
        root.addEventListener('popstate', () => {
          const $view = getEditorialSearchView();
          if ($view.length) {
            updatePastEventsToggle($view);
            refreshEditorialSearchView($view);
          }
        });
      });

      once('editorial-search-ajax-complete', 'html').forEach((root) => {
        $(root).on('ajaxComplete.editorialSearchEventSort', (event, xhr, settings) => {
          if (!(settings.url || '').includes('views/ajax')) {
            return;
          }

          const $view = getEditorialSearchView();
          updatePastEventsToggle($view);

          if ($view.length && Drupal.behaviors.editorialSearchFacets) {
            Drupal.behaviors.editorialSearchFacets.attach($view[0]);
          }

          if (!pendingEventSortUi) {
            return;
          }

          const { sortBy, sortOrder } = pendingEventSortUi;
          pendingEventSortUi = null;
          updateSortControls($view, sortBy, sortOrder);
        });
      });
    },
  };
})(jQuery, Drupal, once, drupalSettings);
